import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception {
		       Scanner sc = new Scanner(System.in);
		       
		       int t = sc.nextInt();
		       StringBuilder ans = new StringBuilder();
		       while(t-- > 0){
		           int n = sc.nextInt();
		           long[] arr = new long[3 * n];
		           for(int i = 0; i < 3 * n; i++){
		               arr[i] = sc.nextLong();
		           }
		           Arrays.sort(arr);
		           int tot = 3 * n;
		           long[] prefix = new long[tot + 1];
		           for(int i = 0; i < tot; i++){
		               prefix[i + 1] = prefix[i] + arr[tot - 1 - i];
		           }
		           long[] values = new long[tot + 1];
		           for(int i = 0; i < tot; i++){
		               values[i] = arr[tot - 1 - i];
		           }
		           long max = 0;
		           int d = n;
		           for(int i = 0; i <= n; i++){
		               d = Math.min(d, n - i);
		               while(d > 0){
		                   int d_idx = i + 2 * (d - 1);
		                   long d_sum = values[d_idx] + values[d_idx + 1];
		                   int s_idx = 3 * n - 2 * i - (d - 1) - 1;
		                   long s_val = values[s_idx];
		                   if(d_sum > 3 * s_val){
		                       break;
		                   }
		                   d--;
		               }
		               long curr = 2L * prefix[i] + prefix[i + 2 * d] + 3L * prefix[3 * n - 2 * i - d];
		               max = Math.max(max, curr);
		           }
		           ans.append(max).append("\n");
		}
		System.out.println(ans);
	}
}
